package com.example.jalalidaily;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.time.*;import java.util.*;import org.json.*;
public final class Widgets{
 static final int[] THEMES={R.drawable.widget_day_0,R.drawable.widget_day_1,R.drawable.widget_day_2,R.drawable.widget_day_3,R.drawable.widget_day_4,R.drawable.widget_day_5,R.drawable.widget_day_6};
 static String fa(String s){return s.replace('0','۰').replace('1','۱').replace('2','۲').replace('3','۳').replace('4','۴').replace('5','۵').replace('6','۶').replace('7','۷').replace('8','۸').replace('9','۹');}
 static LocalDate iranToday(){return LocalDate.now(ZoneId.of("Asia/Tehran"));}
 static int weekday(LocalDate d){return (d.getDayOfWeek().getValue()+1)%7;}
 static String date(LocalDate d){int[] a=Jalali.fromGregorian(d);String[] days={"شنبه","یکشنبه","دوشنبه","سه‌شنبه","چهارشنبه","پنجشنبه","جمعه"};return fa(days[weekday(d)]+"، "+Jalali.label(a));}
 static void update(Context c,Class<?> cls,int layout,boolean notes){AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,cls));LocalDate today=iranToday();int[] jalali=Jalali.fromGregorian(today);for(int id:ids){try{RemoteViews views=new RemoteViews(c.getPackageName(),layout);views.setTextViewText(R.id.date_text,date(today));views.setImageViewResource(R.id.widget_header_image,THEMES[weekday(today)]);if(notes){JSONArray tasks=DayBundles.get(c,Jalali.key(jalali));StringBuilder s=new StringBuilder();for(int i=0;i<tasks.length();i++){JSONObject o=tasks.optJSONObject(i);if(o==null)continue;if(s.length()>0)s.append("\n");s.append(o.optBoolean("done")?"✓ ":"○ ").append(o.optString("emoji","📝")).append("  ").append(o.optString("text"));}views.setTextViewText(R.id.notes_text,fa(s.length()==0?"✦  امروز هنوز برنامه‌ای ثبت نشده است":s.toString()));}PendingIntent intent=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);views.setOnClickPendingIntent(R.id.date_text,intent);if(notes)views.setOnClickPendingIntent(R.id.notes_text,intent);manager.updateAppWidget(id,views);}catch(Exception failure){android.util.Log.e("JalaliWidget","Widget update failed",failure);try{RemoteViews fallback=new RemoteViews(c.getPackageName(),layout);fallback.setTextViewText(R.id.date_text,"تقویم شمسی");if(notes)fallback.setTextViewText(R.id.notes_text,"برای مشاهده برنامه‌ها وارد برنامه شوید");manager.updateAppWidget(id,fallback);}catch(Exception ignored){}}}}
 static void refresh(Context c){try{update(c,DateWidget.class,R.layout.widget_date,false);}catch(Exception e){android.util.Log.e("JalaliWidget","Date update",e);}try{update(c,NotesWidget.class,R.layout.widget_notes,true);}catch(Exception e){android.util.Log.e("JalaliWidget","Notes update",e);}}
}